+#!/usr/bin/env node
+import { readFileSync } from "node:fs";
+import path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const usageMessage = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function failUsage(): never {
+  process.stderr.write(usageMessage + "\n");
+  process.exit(2);
+}
+
+function main(): void {
+  const args = process.argv.slice(2);
+  if (args.length === 0 || args[0] !== "plan") {
+    failUsage();
+  }
+  const rest = args.slice(1);
+  // detect unknown options
+  for (const a of rest) {
+    if (a.startsWith("-") && a !== "--json") {
+      failUsage();
+    }
+  }
+  const jsonCount = rest.filter((a) => a === "--json").length;
+  if (jsonCount > 1) failUsage();
+  const isJson = jsonCount === 1;
+  const files = rest.filter((a) => a !== "--json");
+  if (files.length !== 1) failUsage();
+  const fileArg = files[0]!;
+  const resolved = path.resolve(process.cwd(), fileArg);
+
+  let content: string;
+  try {
+    content = readFileSync(resolved, "utf8");
+  } catch (e: unknown) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error: ${msg}\n` + usageMessage + "\n");
+    process.exit(2);
+  }
+
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(content);
+  } catch (e: unknown) {
+    const msg = e instanceof Error ? e.message : String(e);
+    process.stderr.write(`error INVALID_JSON: ${msg}\n`);
+    process.exit(1);
+  }
+
+  let tasks;
+  try {
+    tasks = parseTasks(parsed);
+  } catch (e: unknown) {
+    if (e instanceof TaskPlanError) {
+      const msg = e instanceof Error ? e.message : String(e);
+      process.stderr.write(`error ${e.code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+
+  let result;
+  try {
+    result = planOrder(tasks);
+  } catch (e: unknown) {
+    if (e instanceof TaskPlanError) {
+      const msg = e instanceof Error ? e.message : String(e);
+      process.stderr.write(`error ${e.code}: ${msg}\n`);
+      process.exit(1);
+    }
+    throw e;
+  }
+
+  if (isJson) {
+    process.stdout.write(JSON.stringify({ order: result.order, stages: result.stages }) + "\n");
+  } else {
+    if (result.order.length === 0 && result.stages.length === 0) {
+      process.stdout.write("Order:\n");
+    } else {
+      let out = "";
+      for (let i = 0; i < result.stages.length; i++) {
+        out += `Stage ${i + 1}: ${result.stages[i]!.join(", ")}\n`;
+      }
+      out += `Order: ${result.order.join(", ")}\n`;
+      process.stdout.write(out);
+    }
+  }
+}
+
+main();
