+import { TaskPlanError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of planning tasks: execution order and parallel stages. */
+export interface PlanResult {
+  /** Every task id, in execution order. */
+  order: string[];
+  /** stages[k] is the set of tasks that can run at the earliest in round k. */
+  stages: string[][];
+}
+
+/** Thrown when two or more tasks share the same id. */
+export class DuplicateTaskError extends TaskPlanError {
+  /** Every id that occurs more than once, each once, ordered by first appearance. */
+  readonly taskIds: string[];
+  constructor(taskIds: string[], message?: string) {
+    super("DUPLICATE_ID", message ?? `duplicate task ids: ${taskIds.join(", ")}`);
+    this.taskIds = taskIds;
+  }
+}
+
+/** Thrown when a task depends on an id that does not exist. */
+export class UnknownDependencyError extends TaskPlanError {
+  /** The task that declares the missing dependency. */
+  readonly taskId: string;
+  /** The missing dependency id. */
+  readonly dependency: string;
+  constructor(taskId: string, dependency: string, message?: string) {
+    super("UNKNOWN_DEPENDENCY", message ?? `task "${taskId}" depends on unknown "${dependency}"`);
+    this.taskId = taskId;
+    this.dependency = dependency;
+  }
+}
+
+/** Thrown when the dependency graph contains a cycle. */
+export class CycleError extends TaskPlanError {
+  /** Closed path where first and last ids are equal and each id depends on the next. */
+  readonly cycle: string[];
+  constructor(cycle: string[], message?: string) {
+    super("CYCLE", message ?? `cycle detected: ${cycle.join(" -> ")}`);
+    this.cycle = cycle;
+  }
+}
+
+/**
+ * Plans an execution order for tasks respecting dependencies and priorities.
+ * Implements R1, R2, R3 and R4 of SPEC.md.
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3.1 duplicate ids
+  const count = new Map<string, number>();
+  const firstPos = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const id = tasks[i]!.id;
+    count.set(id, (count.get(id) ?? 0) + 1);
+    if (!firstPos.has(id)) firstPos.set(id, i);
+  }
+  const duplicates: string[] = [];
+  for (const [id, c] of count) {
+    if (c > 1) duplicates.push(id);
+  }
+  if (duplicates.length > 0) {
+    duplicates.sort((a, b) => (firstPos.get(a)! - firstPos.get(b)!));
+    throw new DuplicateTaskError(duplicates);
+  }
+
+  // Map id -> index
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) idToIndex.set(tasks[i]!.id, i);
+
+  // R3.2 unknown dependency
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    for (const dep of t.dependsOn) {
+      if (!idToIndex.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build adjacency with deduplicated dependencies: task idx -> dependency idxs
+  const adj: number[][] = Array.from({ length: n }, () => []);
+  for (let i = 0; i < n; i++) {
+    const seen = new Set<string>();
+    const list: number[] = [];
+    for (const dep of tasks[i]!.dependsOn) {
+      if (!seen.has(dep)) {
+        seen.add(dep);
+        list.push(idToIndex.get(dep)!);
+      }
+    }
+    adj[i] = list;
+  }
+
+  // R3.3 cycle detection (iterative DFS)
+  const state = new Uint8Array(n); // 0 unvisited,1 visiting,2 done
+  const posOf = new Int32Array(n);
+  posOf.fill(-1);
+  const pathStack: number[] = [];
+  // stack frames for DFS
+  type Frame = { node: number; nextIdx: number };
+  for (let start = 0; start < n; start++) {
+    if (state[start] !== 0) continue;
+    const stack: Frame[] = [{ node: start, nextIdx: 0 }];
+    state[start] = 1;
+    pathStack.push(start);
+    posOf[start] = pathStack.length - 1;
+    while (stack.length > 0) {
+      const frame = stack[stack.length - 1]!;
+      const neighbors = adj[frame.node]!;
+      if (frame.nextIdx < neighbors.length) {
+        const w = neighbors[frame.nextIdx++]!;
+        if (state[w] === 0) {
+          state[w] = 1;
+          pathStack.push(w);
+          posOf[w] = pathStack.length - 1;
+          stack.push({ node: w, nextIdx: 0 });
+        } else if (state[w] === 1) {
+          // cycle found
+          const p = posOf[w];
+          const slice = pathStack.slice(p);
+          const cycleIds = slice.map((idx) => tasks[idx]!.id);
+          cycleIds.push(tasks[w]!.id);
+          throw new CycleError(cycleIds);
+        } else {
+          // visited, continue
+        }
+      } else {
+        // done
+        state[frame.node] = 2;
+        const removed = pathStack.pop()!;
+        posOf[removed] = -1;
+        stack.pop();
+      }
+    }
+  }
+
+  // Build reverse adjacency and indegree for further steps
+  const indeg = new Int32Array(n);
+  const revAdj: number[][] = Array.from({ length: n }, () => []);
+  for (let i = 0; i < n; i++) {
+    indeg[i] = adj[i]!.length;
+    for (const depIdx of adj[i]!) {
+      revAdj[depIdx]!.push(i);
+    }
+  }
+
+  // stages: level = 0 if no deps else 1 + max(level of deps)
+  const level = new Int32Array(n);
+  // Kahn for levels
+  const q: number[] = [];
+  let qHead = 0;
+  const indegForLevels = new Int32Array(indeg);
+  for (let i = 0; i < n; i++) if (indegForLevels[i] === 0) q.push(i);
+  while (qHead < q.length) {
+    const u = q[qHead++]!;
+    for (const v of revAdj[u]!) {
+      const cand = level[u]! + 1;
+      if (cand > level[v]!) level[v] = cand;
+      indegForLevels[v]!--;
+      if (indegForLevels[v] === 0) q.push(v);
+    }
+  }
+  let maxLevel = 0;
+  for (let i = 0; i < n; i++) if (level[i]! > maxLevel) maxLevel = level[i]!;
+  const buckets: number[][] = Array.from({ length: maxLevel + 1 }, () => []);
+  for (let i = 0; i < n; i++) buckets[level[i]!]!.push(i);
+  const stages: string[][] = buckets.map((bucket) => {
+    bucket.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    return bucket.map((idx) => tasks[idx]!.id);
+  });
+  // When n>0 bucket empty case not needed; but if empty input already returned
+  // For maxLevel calculation with empty handled. Remove empty? spec says no stage empty, buckets cover 0..maxLevel which all have at least one.
+  // But if n==0 we already returned.
+  // Filter possible empty if gap (should not happen but keep)
+  const filteredStages = stages.filter(() => true);
+
+  // order via priority-aware Kahn (heap)
+  const indegForOrder = new Int32Array(indeg);
+  // Simple binary max-heap
+  type HeapItem = { idx: number; priority: number; pos: number };
+  const heap: HeapItem[] = [];
+  function heapPush(item: HeapItem): void {
+    heap.push(item);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      if (compare(heap[i]!, heap[p]!) < 0) {
+        const tmp = heap[i]!; heap[i] = heap[p]!; heap[p] = tmp;
+        i = p;
+      } else break;
+    }
+  }
+  function compare(a: HeapItem, b: HeapItem): number {
+    if (a.priority !== b.priority) return b.priority - a.priority; // smaller means higher priority first
+    return a.pos - b.pos;
+  }
+  function heapPop(): HeapItem | undefined {
+    if (heap.length === 0) return undefined;
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        let smallest = i;
+        const l = i * 2 + 1;
+        const r = i * 2 + 2;
+        if (l < heap.length && compare(heap[l]!, heap[smallest]!) < 0) smallest = l;
+        if (r < heap.length && compare(heap[r]!, heap[smallest]!) < 0) smallest = r;
+        if (smallest !== i) {
+          const tmp = heap[i]!; heap[i] = heap[smallest]!; heap[smallest] = tmp;
+          i = smallest;
+        } else break;
+      }
+    }
+    return top;
+  }
+  for (let i = 0; i < n; i++) if (indegForOrder[i] === 0) heapPush({ idx: i, priority: tasks[i]!.priority, pos: i });
+  const order: string[] = [];
+  while (heap.length > 0) {
+    const cur = heapPop()!;
+    const u = cur.idx;
+    order.push(tasks[u]!.id);
+    for (const v of revAdj[u]!) {
+      indegForOrder[v]!--;
+      if (indegForOrder[v] === 0) heapPush({ idx: v, priority: tasks[v]!.priority, pos: v });
+    }
+  }
+
+  // If stages had maxLevel 0 but no tasks? already handled
+  // When n>0 but computed stages - if maxLevel is 0, stages has 1 bucket; fine
+  // Edge: n>0 but our buckets length derived from maxLevel, when n==0 we returned
+  const finalStages = n === 0 ? [] : filteredStages;
+
+  return { order, stages: finalStages };
+}
